function loc(value, lang) {
    if (value && typeof value === "object" && ("ru" in value || "en" in value)) {
        return value[lang] || (lang === "ru" ? value.ru : value.en) || value.ru || "";
    }
    return value;
}

// Extra languages live in i18n.<lang>.js and call this with
// { ui: {key: text}, items: {"PRODUCTS:id": {name, full, pitch, about, featuresTitle, ai: [d, ...]}} }.
function addTranslations(lang, pack) {
    window.I18N[lang] = pack.ui;
    const lists = { PRODUCTS: window.PRODUCTS, AGENTS: window.AGENTS, COURSES: window.COURSES };
    Object.entries(pack.items || {}).forEach(([ref, tr]) => {
        const [list, id] = ref.split(":");
        const item = (lists[list] || []).find(x => x.id === id);
        if (!item) return;
        ["name", "full", "pitch", "about", "featuresTitle"].forEach(f => {
            if (tr[f] && item[f] && typeof item[f] === "object") item[f][lang] = tr[f];
        });
        (tr.ai || []).forEach((d, i) => {
            if (d && item.ai && item.ai[i] && item.ai[i].d) item.ai[i].d[lang] = d;
        });
    });
}

